const newItems = [];

// Usamos un loop con índice (i) para saber cuál es el item original
for (let i = 0; i < items.length; i++) {
  const item = items[i];

  // Si el item tiene datos binarios
  if (item.binary) {
    // Recorremos cada adjunto
    for (const key of Object.keys(item.binary)) {
      newItems.push({
        json: item.json, 
        binary: {
          data: item.binary[key] 
        },
        // ESTA ES LA SOLUCIÓN:
        // Le decimos a n8n: "Este nuevo item pertenece al item número 'i' de la entrada"
        pairedItem: { 
          item: i 
        }
      });
    }
  }
}

return newItems;

