const newItems = [];

// Recorremos cada correo recibido
for (const item of $input.all()) {
  if (item.binary) {
    // Recorremos cada archivo adjunto dentro del correo (data, data0, data1...)
    for (const key of Object.keys(item.binary)) {
      newItems.push({
        // Mantenemos los datos JSON del correo (asunto, fecha, etc.)
        json: item.json,
        binary: {
          // IMPORTANTE: Aquí renombramos cualquier "data0, data1" a siempre "data"
          data: item.binary[key] 
        }
      });
    }
  }
}

return newItems;

const output = [];

// Referenciar directamente a Compression2
const compressionItems = $('Compression2').all();

for (const item of compressionItems) {
  // recorremos todos los binarios del item
  for (const key of Object.keys(item.binary || {})) {
    const bin = item.binary[key];
    const fileName = bin.fileName?.toLowerCase() || '';

    // detectamos PDFs por mimeType o extensión
    if (
      bin.mimeType === 'application/pdf' ||
      fileName.endsWith('.pdf')
    ) {
      output.push({
        json: { fileName: bin.fileName || 'archivo.pdf' },
        binary: { data: bin },
      });
    }
  }
}

return output;

const fecha = new Date();

const mesTexto = fecha.toLocaleString('es-CO', { month: 'long' });
const dia = fecha.getDate();
const anio = fecha.getFullYear(); // Agregamos esta línea

return {
  mes: mesTexto,
  dia,
  anio // Lo agregamos al objeto de retorno
};

